import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷二·28","description":"易小帖 - 卷二·28","frontmatter":{"title":"卷二·28","description":"易小帖 - 卷二·28"},"headers":[],"relativePath":"zh/classics/yixiaotie/068.md","filePath":"zh/classics/yixiaotie/068.md"}'),o={name:"zh/classics/yixiaotie/068.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷二·28",tabindex:"-1"},[r("卷二·28 "),e("a",{class:"header-anchor",href:"#卷二·28","aria-label":"Permalink to “卷二·28”"},"​")],-1),e("p",null,"宋人以羲易為先天，文王易為後天，始於陳摶。此竊乾寶「伏羲先天，神農中天，黃帝後天」之說，而改襲之。然不及中天也。先天后天見《文言》，若中天則揚雄《太玄》列九天之名，一曰中天，非中古之謂。後有造為陳氏中天圖者，已可笑矣。至宋咸淳末，有東嘉朱元昇者，全襲其說，作《三易備遺》，以連山為先天，即伏羲易。以歸藏為中天，即黃帝易。以周易為後天，即文王易。此竊乾寶中天之名，而又改其說，以附於陳氏三天之所未備。仍取蔡季通所定河圖洛書，而反之以一至九為河圖，一至十為洛書，悉如劉長民《鈎隱》所傳者，以之糾纏八卦之中，命為易本，乃取陳氏先天圖反覆回互，以當連山。取舊儒納音說，牽強傅會，以當歸藏。然又以禮器引夫子曰「吾得夏時」一語，雜及律歷，枝幹陰陽分合之數，以充連山。欲避文王后天卦位，仍用先天，轉旋四象老少諸說以充歸藏，則又與連山先天歸藏納音之私說，又無所分別。且乾寶以《大傳》天地定位一章為伏羲易，以帝出乎震一章為連山易，而此又竊襲而更改之，以天地定位帝出乎震二章總為連山易，以雷以動之風以散之一章為歸藏易。大易何書？夫子之傳何傳？乃可任意割剝。拗枉揉曲，爾創彼見，我執此臆有如是者，此侮聖言無忌憚之甚者也。元昇中嘉定武舉為處州龍泉等處巡檢，咸淳中兩浙提刑上其書薦之，而不見用。今崑山徐氏雕其書入經解中，凡十卷。",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
